VALUES ('wu-r1', '遏', ARRAY[]::text[], '姬', '姑发', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '寿梦之子，依遗命实行兄终弟及。战死传位弟余祭，吴国继续扩张，国势强盛，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴王诸樊"}]'::jsonb, NULL, NULL, '诸樊')
