VALUES ('wu-r2', '余祭', ARRAY[]::text[], '姬', '姑发', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '诸樊之弟，在位仅三年。继续实行兄终弟及，传位余昧，国势平稳，维持扩张，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴王余祭"}]'::jsonb, NULL, NULL, '余祭')
