VALUES ('wu-r3', '余眛', ARRAY[]::text[], '姬', '姑发', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '余祭之弟，在位十六年。兄终弟及末代，传位诸樊子僚，吴国政局动荡不安，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴王余昧"}]'::jsonb, NULL, NULL, '余昧')
