VALUES ('wu-r4', '僚', ARRAY[]::text[], '姬', '姑发', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '诸樊之侄，在位十一年。遭公子光（阖闾）刺杀，吴国权力更迭，政局动荡，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴王僚"}]'::jsonb, NULL, NULL, '僚')
