VALUES ('helu', '阖闾', ARRAY[]::text[], '姬', '姑发', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '弑僚自立，任用伍子胥、孙武。破楚入郢，与越王勾践争霸，战死槜李，吴国霸业奠基，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/阖闾"}]'::jsonb, NULL, NULL, '阖闾')
