VALUES ('wu-fu-gai', '夫概', ARRAY[]::text[], '姬', '姑发', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '阖闾之弟。前505年自立为吴王，不久败走楚国；见吴国君主列表。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴王夫概"}]'::jsonb, NULL, NULL, '夫概')
