VALUES ('fu-chai', '夫差', ARRAY[]::text[], '姬', '姑发', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '阖闾之子，数次伐越。夫椒战后为勾践所灭，吴国亡，夫差自杀，霸业终结，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴王夫差"}]'::jsonb, NULL, NULL, '夫差')
