VALUES ('sun-wu', '孙武', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['军事家'], '齐国军事家，著《孙子兵法》，传为吴王阖闾将；《史记》称他向阖闾进呈兵法并训练吴军；其生平记载有限，兵书作者身份亦有学术讨论。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙武"}]'::jsonb, NULL, NULL, NULL)
