VALUES ('wu-zixu', '伍子胥', ARRAY[]::text[], NULL, NULL, -559, 1, NULL, 'year', -484, 1, NULL, 'year', ARRAY['军事家','政治家'], '楚人，助吴王阖闾破楚入郢，后被夫差赐死；夫差听信伯嚭谗言，令其自尽并投尸江中；其故事成为忠谏遭谗的典故。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/伍子胥"}]'::jsonb, NULL, NULL, NULL)
