VALUES ('wu-chunqiu', '吴', ARRAY['吴','吴国'], NULL, 'cn', 'east_asia', -1100, 1, NULL, 'year', -473, 12, NULL, 'month', -13188, -5653, 'ochre', NULL, NULL, '传世世系上溯至泰伯；《史记·吴太伯世家》记载武王克殷时周章已君吴，本项目以西周建国年（前1046）为周章起年确定锚点。锚点前后的无年表连续君主分别按世系均分，失考边标为 interpolated；寿梦起始保留前585年年表锚点。前473年越灭吴。')
